#include <stdio.h>
#include <string.h>
void countingSort(int arr[], int n) {
int output[n];
int max = arr[0];
for (int i = 1; i < n; i++)
if (arr[i] > max) max = arr[i];
int count[max + 1];
memset(count, 0, sizeof(count));
// 计数
for (int i = 0; i < n; i++)
count[arr[i]]++;
// 累加
for (int i = 1; i <= max; i++)
count[i] += count[i - 1];
// 反向放置（保持稳定性）
for (int i = n - 1; i >= 0; i--) {
output[count[arr[i]] - 1] = arr[i];
count[arr[i]]--;
}
// 拷贝回原数组
for (int i = 0; i < n; i++)
arr[i] = output[i];
}
int main() {
int arr[] = {2, 5, 3, 0, 2, 3, 0, 3};
int n = sizeof(arr) / sizeof(arr[0]);
countingSort(arr, n);
for (int i = 0; i < n; i++)
printf("%d ", arr[i]);
return 0;
}
